  { const gm = { 'dk-gSize': 'size', 'dk-gLevel': 'level', 'dk-gLevels': 'levels', 'dk-gEnv': 'env', 'dk-gType': 'type' }; if (gm[el.id]) { UI.genP[gm[el.id]] = el.value; saveUI(); return paint(); } if (el.id === 'dk-gMine') { UI.genP.mine = el.checked; saveUI(); return; } }
