  if (s.onHit) L.push(`On a hit with it: +${s.onHit.dice}${s.onHit.type ? ' ' + s.onHit.type : ''} damage — ${s.onHit.ask ? 'a button on the attack, for when it applies' : 'added every hit'} (doubled on a crit)`);
